css:
/* @prim:begin 50-term-definition */
.term{position:relative;display:inline}
.term-b{all:unset;display:inline;cursor:pointer;text-decoration:underline dotted;text-decoration-color:color-mix(in srgb,currentColor 55%,transparent);text-underline-offset:3px;border-radius:var(--ds-r-xs)}
.term-b:hover,.term-b[aria-expanded="true"]{color:var(--cyan);text-decoration-style:solid;text-decoration-color:currentColor}
.term-b:focus-visible{outline:3px solid var(--cyan);outline-offset:2px}
.term-tip{position:absolute;z-index:5;left:0;top:calc(100% + 6px);width:max-content;max-width:min(280px,calc(100vw - 48px));background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:var(--ds-r-sm);padding:10px 12px;box-shadow:0 2px 8px rgba(0,0,0,.14);font-size:.9rem;line-height:1.45;font-weight:400;text-align:left;white-space:normal;text-transform:none;letter-spacing:normal}
.term-tip[hidden]{display:none}
.term-tip.up{top:auto;bottom:calc(100% + 6px)}
.term-tip b{display:block;margin:0 0 2px}
.term-go{display:inline-flex;align-items:center;min-height:32px;margin-top:4px;color:var(--cyan);font-weight:600;text-underline-offset:3px}
.term-go:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}
[data-space="roomy"] .term-tip{line-height:1.8}
/* @prim:end 50-term-definition */

