function kIcon(k){return '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+KI[k]+'</svg>';}
function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var TD={term:'MVP',def:'Minimum viable product: the smallest working version that proves the idea with real users.',href:'#glossary-mvp'};
var tdN=0;function kitTerm(d){var u='td'+(++tdN);return '<span class="term"><button type="button" class="term-b" aria-expanded="false" aria-describedby="'+u+'">'+kEsc(d.term)+'</button><span class="term-tip" id="'+u+'" role="tooltip" hidden><b>'+kEsc(d.term)+'</b>'+kEsc(d.def)+(d.href?' <a class="term-go" href="'+kEsc(d.href)+'">Full entry</a>':'')+'</span></span>';}
function kitTermWire(root){var pin=null,quiet=false;function show(b,on){var t=b.nextElementSibling;t.hidden=!on;b.setAttribute('aria-expanded',String(on));if(!on)return;t.style.left='0px';t.classList.remove('up');var box=(b.closest('[data-term-box]')||document.documentElement).getBoundingClientRect(),vw=document.documentElement.clientWidth,L=Math.max(box.left,0)+8,R=Math.min(box.right,vw)-8,r=t.getBoundingClientRect();if(r.right>R)t.style.left=(R-r.right)+'px';r=t.getBoundingClientRect();if(r.left<L)t.style.left=(parseFloat(t.style.left)+L-r.left)+'px';if(r.bottom>innerHeight-4&&b.getBoundingClientRect().top-r.height-6>=4)t.classList.add('up');}
function off(){root.querySelectorAll('.term-b[aria-expanded="true"]').forEach(function(b){show(b,false);});pin=null;}
root.addEventListener('mouseover',function(e){var w=e.target.closest('.term');if(w&&!pin)show(w.querySelector('.term-b'),true);});root.addEventListener('mouseout',function(e){var w=e.target.closest('.term');if(w&&!pin&&!w.contains(e.relatedTarget))show(w.querySelector('.term-b'),false);});
root.addEventListener('focusin',function(e){var b=e.target.closest('.term-b');if(b&&!pin&&!quiet)show(b,true);});root.addEventListener('focusout',function(e){var w=e.target.closest('.term');if(w&&!pin&&!w.contains(e.relatedTarget))show(w.querySelector('.term-b'),false);});
root.addEventListener('keydown',function(e){if(e.key!=='Escape')return;var b=pin||root.querySelector('.term-b[aria-expanded="true"]');if(!b)return;e.preventDefault();off();quiet=true;b.focus();quiet=false;});
root.addEventListener('click',function(e){var b=e.target.closest('.term-b');if(b){if(pin===b)off();else{off();pin=b;show(b,true);}return;}if(pin&&!e.target.closest('.term'))off();});return show;}
var stg=kSlot();stg.setAttribute('data-term-box','');stg.innerHTML='<p style="margin:0 0 9rem">Step 1 ends with a scoped '+kitTerm(TD)+' plan you can take to any builder.</p>';var tdShow=kitTermWire(document.body);
STATES.forEach(function(s,i){var el=kSlot(i);el.setAttribute('data-term-box','');el.innerHTML='<p'+(s[0]?' style="margin:0 0 8rem"':'')+'>A scoped '+kitTerm(TD)+' plan.</p>';if(s[0]){var b=el.querySelector('.term-b');requestAnimationFrame(function(){tdShow(b,true);});}});
